	private record ExistenceDriver(Filter filter, ExistencePredicate predicate, List<String> leftNames,
			List<String> rightNames) {
	}

	private static final class LocalDistinct extends Distinct {

		private LocalDistinct(TupleExpr arg) {
			super(arg);
		}
	}

	private static final class CompatibilityIndex {
		private final SummaryTable table;
		private final List<String> correlationNames;
		private final CompatibilityNode root = new CompatibilityNode();

		private CompatibilityIndex(SummaryTable table, Collection<String> correlationNames) {
			this.table = table;
			this.correlationNames = List.copyOf(correlationNames);
			for (Map.Entry<GroupKey, Moments> entry : table.groups.entrySet()) {
				CompatibilityNode node = root;
				for (String correlationName : this.correlationNames) {
					Value value = table.value(entry.getKey(), correlationName);
					node = value == null ? node.unboundChild() : node.boundChild(value);
				}
				node.rows.add(new CompatibilityRow(entry.getKey(), entry.getValue()));
			}
		}

		private void find(SummaryTable leftTable, GroupKey leftKey, List<CompatibilityRow> matches) {
			find(root, 0, leftTable, leftKey, matches);
		}

		private void find(CompatibilityNode node, int depth, SummaryTable leftTable, GroupKey leftKey,
				List<CompatibilityRow> matches) {
			if (depth == correlationNames.size()) {
				matches.addAll(node.rows);
				return;
			}
			Value leftValue = leftTable.value(leftKey, correlationNames.get(depth));
			if (leftValue == null) {
				if (node.unbound != null) {
					find(node.unbound, depth + 1, leftTable, leftKey, matches);
				}
				for (CompatibilityNode child : node.bound.values()) {
					find(child, depth + 1, leftTable, leftKey, matches);
				}
				return;
			}
			CompatibilityNode bound = node.bound.get(leftValue);
			if (bound != null) {
				find(bound, depth + 1, leftTable, leftKey, matches);
			}
			if (node.unbound != null) {
				find(node.unbound, depth + 1, leftTable, leftKey, matches);
			}
		}
	}

	private static final class CompatibilityNode {
		private final Map<Value, CompatibilityNode> bound = new LinkedHashMap<>();
		private final List<CompatibilityRow> rows = new ArrayList<>();
		private CompatibilityNode unbound;

		private CompatibilityNode boundChild(Value value) {
			return bound.computeIfAbsent(value, ignored -> new CompatibilityNode());
		}

		private CompatibilityNode unboundChild() {
			if (unbound == null) {
				unbound = new CompatibilityNode();
			}
			return unbound;
		}
	}

	private record CompatibilityRow(GroupKey key, Moments moments) {
	}

	private static final class SummaryTable {
		private final List<String> groupNames;
		private final Map<String, Integer> groupNameIndexes;
		private final Map<GroupKey, Moments> groups = new LinkedHashMap<>();
		private Map<List<String>, CompatibilityIndex> compatibilityIndexes;

		private SummaryTable(Collection<String> groupNames) {
			this.groupNames = List.copyOf(groupNames);
			Map<String, Integer> indexes = new HashMap<>();
			for (int i = 0; i < this.groupNames.size(); i++) {
				indexes.put(this.groupNames.get(i), i);
			}
			this.groupNameIndexes = Map.copyOf(indexes);
		}

		private void add(GroupKey key, long rowCount, long[] laneSums) {
			groups.computeIfAbsent(key, ignored -> new Moments(laneSums.length)).add(rowCount, laneSums);
		}

		private Value value(GroupKey key, String name) {
			Integer index = groupNameIndexes.get(name);
			if (index == null) {
				throw new IllegalArgumentException("Binding is not grouped: " + name);
			}
			return key.values[index];
		}

		private Value valueOrNull(GroupKey key, String name) {
			Integer index = groupNameIndexes.get(name);
			return index == null ? null : key.values[index];
		}

		private CompatibilityIndex compatibilityIndex(Collection<String> correlationNames) {
			if (compatibilityIndexes == null) {
				compatibilityIndexes = new HashMap<>();
			}
			List<String> key = List.copyOf(correlationNames);
			return compatibilityIndexes.computeIfAbsent(key, ignored -> new CompatibilityIndex(this, key));
		}
	}

	private static final class Moments {
		private long rowCount;
		private final long[] laneSums;

		private Moments(int laneCount) {
			laneSums = new long[laneCount];
		}

		private void add(long rows, long[] lanes) {
			rowCount = Math.addExact(rowCount, rows);
			for (int lane = 0; lane < laneSums.length; lane++) {
				laneSums[lane] += lanes[lane];
			}
		}
	}

	private static final class GroupKey {
		private final Value[] values;
		private final int hash;

		private GroupKey(Value[] values) {
			this.values = values.clone();
			this.hash = Arrays.hashCode(this.values);
		}

		@Override
		public boolean equals(Object other) {
			return this == other || other instanceof GroupKey key && Arrays.equals(values, key.values);
		}

		@Override
		public int hashCode() {
			return hash;
		}
	}

	private static final class InvocationKey {
		private final List<String> groupNames;
		private final List<String> inputNames;
		private final Value[] inputValues;
		private final int hash;

		private InvocationKey(List<String> groupNames, List<String> inputNames, Value[] inputValues) {
			this.groupNames = groupNames;
			this.inputNames = List.copyOf(inputNames);
			this.inputValues = inputValues.clone();
			this.hash = 31 * (31 * groupNames.hashCode() + this.inputNames.hashCode())
					+ Arrays.hashCode(this.inputValues);
		}

		@Override
		public boolean equals(Object other) {
			return this == other || other instanceof InvocationKey key && groupNames.equals(key.groupNames)
					&& inputNames.equals(key.inputNames) && Arrays.equals(inputValues, key.inputValues);
		}

		@Override
		public int hashCode() {
			return hash;
		}
	}

	private static final class LocalJoin extends Join {

		private LocalJoin(TupleExpr leftArg, TupleExpr rightArg) {
			super(leftArg, rightArg);
		}
	}
